// HTML: <input type="text" id="name" placeholder="Введите имя">
const input = document.querySelector("#name");

// Читаем текущее значение:
console.log(input.value);  // "" — пустое при загрузке

// Значение обновляется при вводе:
input.addEventListener("input", () => {
  console.log("Пользователь ввёл:", input.value);
});

// Text input
const name = document.querySelector("#name");
console.log(name.value);  // "Алиса"

// Number input — value ВСЁ ЕЩЁ строка!
const age = document.querySelector("#age");
console.log(typeof age.value);  // "string" — даже если ввёл 25

// Чтобы получить число — приводим:
const ageNum = Number(age.value);  // 25

// Select
const select = document.querySelector("#country");
console.log(select.value);  // "RU"

// Checkbox
const agree = document.querySelector("#agree");
console.log(agree.checked);  // true/false

// Функции валидации
function isEmpty(str) {
  return str.trim().length === 0;  // проверка на пустоту
}

function isEmail(str) {
  return /^[\w.-]+@[\w.-]+\.[a-z]+$/.test(str);  // проверка email
}

function isMinLength(str, min) {
  return str.trim().length >= min;
}

// Использование:
const name = document.querySelector("#name").value;
if (isEmpty(name)) {
  console.log("Имя не может быть пустым");
}
if (!isEmail(document.querySelector("#email").value)) {
  console.log("Некорректный email");
}

