const input = document.querySelector("#email");
const error = document.createElement("span");
error.className = "error";
error.style.color = "red";

function validateEmail(email) {
  if (!email.includes("@")) {
    error.textContent = "Email должен содержать @";
    input.parentElement.appendChild(error);  // показываем ошибку
    return false;
  }
  // Если всё ок — скрываем ошибку
  error.remove();
  return true;
}

input.addEventListener("input", () => {
  validateEmail(input.value);
});

const form = document.querySelector("form");

form.addEventListener("submit", (event) => {
  event.preventDefault();  // не перезагружаем

  const name = document.querySelector("#name").value;
  const email = document.querySelector("#email").value;
  const errors = [];

  if (name.trim() === "") errors.push("Введите имя");
  if (!email.includes("@")) errors.push("Введите email");

  if (errors.length > 0) {
    console.log(errors.join(", "));  // показать ошибки
    return;  // не отправляем
  }

  console.log("Форма отправлена!");  // данные корректны
});

// БАГ: не очищаем и не приводим тип
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const num = document.querySelector("#number").value;  // "5"
  const result = num + num;  // "55" — строки!
  console.log(result);  // "55" вместо 10
});

// ПРАВИЛЬНО: приводим тип и очищаем
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const num = Number(document.querySelector("#number").value);
  const result = num + num;  // 10
  console.log(result);
  document.querySelector("#number").value = "";  // очистка
});

